entries[298927] = { ["name"] = "Massenmahlung - Zin'anthiden", ["text"] = "Wirken in 2 sek.\nReagenzien:\nZin'anthide (20)\nMahlt mehrere Zin'anthiden gleichzeitig.\nBeruf:\nInschriftenkunde von Battle for Azeroth (155)\nLehrer:\nNarv\nZone:\nNazjatar\nKosten:\n77\n50\n\nZin'anthide\nHandwerksmaterial\n\"Wird von Spielercharakteren gesammelt, die den Beruf Kräuterkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nGeplündert von: Fleischfressender Peitscher\nDropchance: 96.76%" }
