entries[298995] = { ["name"] = "Abyssischer Alchemistenstein", ["text"] = "Wirken in 3 sek.\nReagenzien:\nZin'anthide (150), Ankerkraut (50), Expulsom (30)\nStellt einen abyssischen Alchemistenstein her.\nBeruf:\nAlchemie von Battle for Azeroth (165)\nLehrer:\nNarv\nZone:\nNazjatar\nKosten:\n1\n5\n\nAbyssischer Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+ 10 Vielseitigkeit\n\nPrismatischer Sockel\n\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 27 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n50\nBenötigt Alchemie von Kul Tiras\n(165)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
entries[298996] = { ["name"] = "Zermalmender Alchemistenstein", ["text"] = "Wirken in 3 sek.\nReagenzien:\nZin'anthide (200), Ankerkraut (65), Expulsom (35)\nStellt einen zermalmenden Alchemistenstein her.\nBeruf:\nAlchemie von Battle for Azeroth (165)\nEntdeckung:\nAbyssischer Alchemistenstein\n\nZermalmender Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+ 11 Vielseitigkeit\n\nPrismatischer Sockel\n\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 28 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n50\nBenötigt Alchemie von Kul Tiras\n(165)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
entries[298997] = { ["name"] = "Erwachter Alchemistenstein", ["text"] = "Wirken in 3 sek.\nReagenzien:\nZin'anthide (250), Ankerkraut (75), Expulsom (40)\nStellt einen erwachten Alchemistenstein her.\nBeruf:\nAlchemie von Battle for Azeroth (165)\nEntdeckung:\nZermalmender Alchemistenstein\n\nErwachter Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+ 12 Vielseitigkeit\n\nPrismatischer Sockel\n\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 31 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n50\nBenötigt Alchemie von Kul Tiras\n(165)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
