entries[299326] = { ["name"] = "Schleim", ["text"] = "Nahkampfreichweite\nSofort 2 sek. Abklingzeit\nVerursacht Naturschaden und schleimt alle Gegner in der Nähe für 8 Sek. ein, wodurch sich ihre Bewegungsgeschwindigkeit verringert und sie Schaden erleiden." }
entries[299327] = { ["name"] = "Fragment der Leere", ["text"] = "Sofort 2 sek. Abklingzeit\nSchleudert ein dunkles Geschoss auf die Position eines Spielercharakters, das allen Spielercharakteren innerhalb von 5 Metern 12 Schattenschaden zufügt und eine schädliche Lache aus Leerenmagie hinterlässt." }
