entries[299329] = { ["name"] = "Kugelfisch" }
entries[299330] = { ["name"] = "Kugelfisch", ["text"] = "30 Meter Reichweite\nSofort 15 sek. Abklingzeit\nSpuckt einen Kugelfisch auf den Zielpunkt. Nach 3 Sek. platzt der Fisch auf." }
entries[299332] = { ["name"] = "Biolumineszentes Licht", ["text"] = "Sofort\nHüllt Eure Umgebung in biolumineszentes Licht, sodass Ihr die Spuren von Azeritrückständen sehen könnt." }
entries[299333] = { ["name"] = "Lebensblut", ["text"] = "Azerit Essenz\nAlle 1-25 Sek. entspringt dem Boden in der Nähe ein Lebensblutsplitter, der 18 lang bestehen bleibt.\n\nLebensblutsplitter\nDer Splitter gewährt Euch und allen anderen Verbündeten, die 'Resonanz der Weltader' verwenden, innerhalb von 12 Metern um den Splitter 13 Eures jeweiligen Primärwerts. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren." }
entries[299334] = { ["name"] = "Resonanz der Weltader", ["text"] = "Azerit Essenz\nSofort 1 min Abklingzeit\nKonzentriert Energie in das Herz von Azeroth und lässt 3 Lebensblutsplitter in der Nähe aus dem Boden schießen, die 18 Sek. lang bestehen bleiben. Erhöht außerdem den durch Lebensblutsplitter erhaltenen Primärwert 18 Sek. lang um 300%.\n\nLebensblutsplitter\nErhöht Euren Primärwert und den Primärwert jedes weiteren Verbündeten, der 'Resonanz der Weltader' benutzt, um 13 , solange Ihr Euch innerhalb von 12 Metern um den Lebensblutsplitter aufhaltet. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren." }
entries[299335] = { ["name"] = "Fokussierte Energie", ["text"] = "Azerit Essenz\nEure Schaden verursachenden Zauber und Fähigkeiten gewähren Euch 4 Sek. lang [Quellwert] Tempo. Dieser Effekt ist bis zu 10-mal stapelbar. Dieses Tempo geht verloren, sobald Ihr aufhört, Zauber oder Fähigkeiten gegen das ursprüngliche Ziel einzusetzen.", ["unresolvedValues"] = true }
entries[299336] = { ["name"] = "Fokussierter Azeritstrahl", ["text"] = "Azerit Essenz\nWirken in 1.333 sek. 1.5 min Abklingzeit\nFokussiert überschüssige Azeritenergie in das Herz von Azeroth und setzt sie dann frei, um allen Gegnern vor Euch im Verlauf von 3 Sek. ( 891 * 10) Feuerschaden zuzufügen." }
entries[299337] = { ["name"] = "Fokussierte Energie", ["text"] = "Azerit Essenz\nEure Schaden verursachenden Zauber und Fähigkeiten gewähren Euch 4 Sek. lang [Quellwert] Tempo. Dieser Effekt ist bis zu 10-mal stapelbar. Dieses Tempo geht verloren, sobald Ihr aufhört, Zauber oder Fähigkeiten gegen das ursprüngliche Ziel einzusetzen.\n\nWenn Ihr keine Stapel von 'Fokussierte Energie' habt, gewährt Euer erster Einsatz eines Schadenszaubers oder einer Schadensfähigkeit Euch 3 Stapel.", ["unresolvedValues"] = true }
entries[299338] = { ["name"] = "Fokussierter Azeritstrahl", ["text"] = "Azerit Essenz\nWirken in 1.333 sek. 1.5 min Abklingzeit\nFokussiert überschüssige Azeritenergie in das Herz von Azeroth und setzt sie dann frei, um allen Gegnern vor Euch im Verlauf von 3 Sek. ( 891 * 10) Feuerschaden zuzufügen. Kann aus der Bewegung heraus eingesetzt werden." }
entries[299342] = { ["name"] = "Kugelfisch", ["text"] = "6 Meter Reichweite\nWirken in 2 sek.\nFügt Gegnern in der Nähe Naturschaden zu." }
entries[299343] = { ["name"] = "Reinigungsprotokoll", ["text"] = "Azerit Essenz\nCa. 2 Procs pro Minute\nMUTTER hat Euer Herz von Azeroth um ein Reinigungsprotokoll erweitert, durch das Eure Schaden verursachenden Zauber und Fähigkeiten Euer Ziel mit Azeritenergie überziehen können, die 8 Sek. lang alle 2 Sek. jedem Gegner innerhalb von 8 Metern [ 563 * (1 + Vielseitigkeit)] Feuerschaden zufügt und Euch dabei um [ 255 * (1 + Vielseitigkeit)] Gesundheit heilt.\n\n'Reinigungsprotokoll' fügt Entartungen 50% mehr Schaden zu." }
entries[299344] = { ["name"] = "Schutzblase", ["text"] = "Sofort 10 sek. Abklingzeit\nGewährt 3 Sek. lang Unverwundbarkeit, entfernt alle Gift-, Krankheits- und Magieeffekte und heilt Euch um 35% Eurer maximalen Gesundheit." }
entries[299345] = { ["name"] = "Läuternde Druckwelle", ["text"] = "Azerit Essenz\n40 Meter Reichweite\nSofort 1 min Abklingzeit\nRuft einen läuternden Strahl auf das Zielgebiet herab, der [ 395 * (1 + Vielseitigkeit) * 7] Feuerschaden im Verlauf von 6 Sek. verursacht. Hat eine geringe Chance, alle von MUTTER für unwürdig befundenen Kreaturen sofort zu töten.\n\nAlle vom Strahl getroffenen Entartungen werden für 3 Sek. betäubt." }
entries[299346] = { ["name"] = "Reinigungsprotokoll", ["text"] = "Azerit Essenz\nCa. 2 Procs pro Minute\nMUTTER hat Euer Herz von Azeroth um ein Reinigungsprotokoll erweitert, durch das Eure Schaden verursachenden Zauber und Fähigkeiten Euer Ziel mit Azeritenergie überziehen können, die 8 Sek. lang alle 2 Sek. jedem Gegner innerhalb von 8 Metern [ 563 * (1.25) * (1 + Vielseitigkeit)] Feuerschaden zufügt und Euch dabei um [ 255 * (1 + Vielseitigkeit)] Gesundheit heilt.\n\n'Reinigungsprotokoll' fügt Entartungen 50% mehr Schaden zu." }
entries[299347] = { ["name"] = "Läuternde Druckwelle", ["text"] = "Azerit Essenz\n40 Meter Reichweite\nSofort 1 min Abklingzeit\nRuft einen läuternden Strahl auf das Zielgebiet herab, der [ 395 * (1 + Vielseitigkeit) * 7] Feuerschaden im Verlauf von 6 Sek. verursacht. Hat eine geringe Chance, alle von MUTTER für unwürdig befundenen Kreaturen sofort zu töten.\n\nWenn ein Gegner innerhalb des Strahls stirbt, wird Euer Schaden 8 Sek. lang um 10% erhöht.\n\nAlle vom Strahl getroffenen Entartungen werden für 3 Sek. betäubt." }
entries[299348] = { ["name"] = "Uralte Flamme", ["text"] = "Azerit Essenz\nCa. 1.25 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, das Ziel zu verbrennen oder zu kauterisieren. Gegner erleiden dadurch [Quellwert] Feuerschaden im Verlauf von 10 Sek., Verbündete werden um [Quellwert] Gesundheit im Verlauf von 10 Sek. geheilt.", ["unresolvedValues"] = true }
entries[299349] = { ["name"] = "Konzentrierte Flamme", ["text"] = "Azerit Essenz\n40 Meter Reichweite\nSofort 30 sek. Abklingzeit\n1 Aufladung\nBeschießt Euer Ziel mit einer Kugel aus konzentrierten Flammen, die einem Gegner [ 824 * (1 + Vielseitigkeit)] Feuerschaden zufügen oder einen Verbündeten um [ 824 * (1 + Vielseitigkeit)] Gesundheit heilen. Die Flammen fügen dem Ziel danach zusätzlich 75% des Schadens im Verlauf von 6 Sek. zu oder heilen es um diesen Wert.\n\nImmer wenn Ihr 'Konzentrierte Flamme' einsetzt, erhöht sich der Schaden oder die Heilung um 100%. Dieser Bonus wird nach jedem dritten Einsatz zurückgesetzt." }
entries[299350] = { ["name"] = "Uralte Flamme", ["text"] = "Azerit Essenz\nCa. 1.25 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, das Ziel zu verbrennen oder zu kauterisieren. Gegner erleiden dadurch [Quellwert] Feuerschaden im Verlauf von 10 Sek., Verbündete werden um [Quellwert] Gesundheit im Verlauf von 10 Sek. geheilt. Bis zu 3-mal stapelbar.", ["unresolvedValues"] = true }
entries[299351] = { ["name"] = "Pakt der Nachtfae" }
entries[299352] = { ["name"] = "Pakt der Nekrolords" }
entries[299353] = { ["name"] = "Konzentrierte Flamme", ["text"] = "Azerit Essenz\n40 Meter Reichweite\nSofort 30 sek. Abklingzeit\n1 Aufladung\nBeschießt Euer Ziel mit einer Kugel aus konzentrierten Flammen, die einem Gegner [ 824 * (1 + Vielseitigkeit)] Feuerschaden zufügen oder einen Verbündeten um [ 824 * (1 + Vielseitigkeit)] Gesundheit heilen. Die Flammen fügen dem Ziel danach zusätzlich 75% des Schadens im Verlauf von 6 Sek. zu oder heilen es um diesen Wert.\n\nImmer wenn Ihr 'Konzentrierte Flamme' einsetzt, erhöht sich der Schaden oder die Heilung um 100%. Dieser Bonus wird nach jedem dritten Einsatz zurückgesetzt.\nMaximal 2 Aufladungen." }
entries[299354] = { ["name"] = "Kondensierte Lebenskraft", ["text"] = "Azerit Essenz\nCa. 2 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine hohe Chance, das Ziel mit einem Azeritstachel aufzuspießen, der ihm [ 660 * (1 + Vielseitigkeit) * (1.25)] Feuerschaden zufügt." }
entries[299355] = { ["name"] = "Wächter von Azeroth", ["text"] = "Azerit Essenz\nSofort 3 min Abklingzeit\nBeschwört einen Wächter von Azeroth, der Euch 30 Sek. lang im Kampf beisteht und Euer Ziel alle 2.5 Sek. mit Azeritstacheln aufspießt, die [ 660 * (1 + Vielseitigkeit) * (1.25)] Feuerschaden verursachen. Der Wächter verschießt alle 8 Sek. eine Salve aus Azeritstacheln auf sein Ziel, die allen Gegnern in der Nähe 670 Feuerschaden zufügen." }
entries[299356] = { ["name"] = "Kiste halten" }
entries[299357] = { ["name"] = "Kondensierte Lebenskraft", ["text"] = "Azerit Essenz\nCa. 2 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine hohe Chance, das Ziel mit einem Azeritstachel aufzuspießen, der ihm [ 660 * (1 + Vielseitigkeit) * (1.25)] Feuerschaden zufügt.\n\nWenn ein Azeritstachel Schaden verursacht, wird sämtlicher Schaden, den Ihr diesem Ziel zufügt, 6 Sek. lang um 3% erhöht." }
entries[299358] = { ["name"] = "Wächter von Azeroth", ["text"] = "Azerit Essenz\nSofort 3 min Abklingzeit\nBeschwört einen Wächter von Azeroth, der Euch 30 Sek. lang im Kampf beisteht und Euer Ziel alle 2.5 Sek. mit Azeritstacheln aufspießt, die [ 660 * (1 + Vielseitigkeit) * (1.25)] Feuerschaden verursachen. Der Wächter verschießt alle 8 Sek. eine Salve aus Azeritstacheln auf sein Ziel, die allen Gegnern in der Nähe 670 Feuerschaden zufügen.\n\nJedes Mal, wenn der Wächter von Azeroth einen Zauber wirkt, erhaltet Ihr 2% Tempo (bis zu 5 - mal stapelbar). Dieser Effekt endet, wenn der Wächter von Azeroth verschwindet." }
entries[299359] = { ["name"] = "Motor des unablässigen Fortschritts", ["text"] = "Alle 2 Sek. verstärkt Euch das Herz von Azeroth mit 3 Tempo, Meisterschaft oder kritischem Trefferwert. Nach 10 erreichten Stapeln von Tempo, Meisterschaft oder kritischem Trefferwert überlädt sich das Herz von Azeroth vorübergehend und verdoppelt 8 Sek. lang die Effekte von 'Motor des unablässigen Fortschritts'. Danach werden die Stapel entfernt.\n\nWenn Ihr einen Stapel von einem der Antriebseffekte erhaltet, habt Ihr eine Chance von 20%, einen zweiten Stapel zu erzeugen." }
entries[299360] = { ["name"] = "Motor des unablässigen Fortschritts", ["text"] = "Sofort 2 min Abklingzeit\nErschafft ein Feld aus Azeritenergie an Eurem aktuellen Standort, das 10 Sek. lang anhält. Während Ihr Euch in diesem Bereich aufhaltet, erhaltet Ihr alle 0.5 Sek. einen Stapel von 'Motor des Tempos', 'Motor der Meisterschaft' und 'Motor des kritischen Treffers'.\n\nWährend Ihr Euch im Effektbereich von 'Motor des unablässigen Fortschritts' aufhaltet, erleidet Ihr 10% weniger Schaden." }
entries[299361] = { ["name"] = "Motor des unablässigen Fortschritts", ["text"] = "Alle 2 Sek. verstärkt Euch das Herz von Azeroth mit 3 Tempo, Meisterschaft oder kritischem Trefferwert. Nach 10 erreichten Stapeln von Tempo, Meisterschaft oder kritischem Trefferwert überlädt sich das Herz von Azeroth vorübergehend und verdoppelt 8 Sek. lang die Effekte von 'Motor des unablässigen Fortschritts'. Danach werden die Stapel entfernt.\n\nWenn Ihr einen Stapel von einem der Antriebseffekte erhaltet, habt Ihr eine Chance von 20%, einen zusätzlichen Stapel zu erzeugen, und eine Chance von 10%, alle drei Antriebseffekte anstatt nur eines zufälligen zu erhalten." }
entries[299362] = { ["name"] = "Marsch der Murlocs", ["text"] = "150 Meter Reichweite\nSofort\nFügt dem Ziel Naturschaden zu." }
entries[299363] = { ["name"] = "Marsch der Murlocs" }
entries[299364] = { ["name"] = "Motor des unablässigen Fortschritts", ["text"] = "Sofort 2 min Abklingzeit\nErschafft ein Feld aus Azeritenergie an Eurem aktuellen Standort, das 10 Sek. lang anhält. Während Ihr Euch in diesem Bereich aufhaltet, erhaltet Ihr alle 0.5 Sek. einen Stapel von 'Motor des Tempos', 'Motor der Meisterschaft' und 'Motor des kritischen Treffers'.\n\nWährend Ihr Euch im Effektbereich von 'Motor des unablässigen Fortschritts' aufhaltet, erleidet Ihr 10% weniger Schaden.\n\nWenn Ihr 'Motor des unablässigen Fortschritts' aktiviert, wird die Stapelanzahl von 'Motor des Tempos', 'Motor der Meisterschaft' oder 'Motor des kritischen Treffers' sofort um 100% erhöht." }
entries[299365] = { ["name"] = "Marsch der Murlocs" }
entries[299366] = { ["name"] = "Marsch der Murlocs", ["text"] = "20 Meter Reichweite\nKanalisiert (Wirken in 5 sek.) 20 sek. Abklingzeit\nBefiehlt einer Legion Murlocs, vorwärtszumarschieren." }
entries[299367] = { ["name"] = "Streben nach Perfektion", ["text"] = "Azerit Essenz\nVerringert die Abklingzeit von ' ' um [(( 6849 + 3320) /- 100) ; Min 10, Max 25]%.\n\nDas Aktivieren von ' ' heilt Euch sofort um 5% der maximalen Gesundheit." }
entries[299368] = { ["name"] = "Vision der Perfektion", ["text"] = "Azerit Essenz\nEure Zauber und Fähigkeiten haben eine Chance, ' ' für 35% der Grunddauer zu aktivieren ." }
entries[299369] = { ["name"] = "Streben nach Perfektion", ["text"] = "Azerit Essenz\nVerringert die Abklingzeit von ' ' um [(( 6849 + 3320) /- 100) ; Min 10, Max 25]% und erhöht Eure Vielseitigkeit um 18 .\n\nDas Aktivieren von ' ' heilt Euch sofort um 5% der maximalen Gesundheit." }
entries[299370] = { ["name"] = "Vision der Perfektion", ["text"] = "Azerit Essenz\nEure Zauber und Fähigkeiten haben eine Chance, ' ' für 35% der Grunddauer zu aktivieren .\n\nWenn 'Vision der Perfektion' aktiviert wird, erhaltet Ihr und bis zu 2 Verbündete in der Nähe 10 Sek. lang 24 Tempo." }
entries[299371] = { ["name"] = "Klarträume", ["text"] = "Azerit Essenz\nEure Zauber und Fähigkeiten haben eine Chance, in Höhe von 50% der verbrauchten Menge zu erstatten und Euch um [ 764 * 1.5 * (1 + Vielseitigkeit)] Gesundheit zu heilen ." }
entries[299372] = { ["name"] = "Erinnerung an den Klartraum", ["text"] = "Azerit Essenz\nSofort 2 min Abklingzeit\nMacht Euren Geist frei und stimmt Euch auf das Herz von Azeroth ein. Dadurch erzeugt Ihr 100% mehr . Hält 15 Sek. lang an." }
entries[299373] = { ["name"] = "Klarträume", ["text"] = "Azerit Essenz\nEure Zauber und Fähigkeiten haben [eine Chance, in Höhe von 50% der verbrauchten Menge zu erstatten], Euch um [ 764 * (1.5) * (1 + Vielseitigkeit)] Gesundheit zu heilen und Eure Vielseitigkeit 8 Sek. lang um 74 zu erhöhen." }
entries[299374] = { ["name"] = "Erinnerung an den Klartraum", ["text"] = "Azerit Essenz\nSofort 2 min Abklingzeit\nMacht Euren Geist frei und stimmt Euch auf das Herz von Azeroth ein. Dadurch erzeugt Ihr 100% mehr . Zusätzlich erhaltet Ihr 66 Lebensraub. Hält 15 Sek. lang an." }
entries[299375] = { ["name"] = "Tollkühne Kraft", ["text"] = "Azerit Essenz\nWenn eine Eurer Fähigkeiten nicht kritisch trifft, besteht eine hohe Chance, dass Ihr 'Tollkühne Kraft' erhaltet. Wenn 'Tollkühne Kraft' 20 Stapel erreicht, wird Euer kritischer Trefferwert 4 Sek. lang um 70% erhöht." }
entries[299376] = { ["name"] = "Die Ungezügelte Kraft", ["text"] = "Azerit Essenz\n40 Meter Reichweite\nSofort 45 sek. Abklingzeit\nEntfesselt die Kräfte in Eurem Herz von Azeroth und schießt Azeritsplitter auf Euer Ziel, das dadurch im Verlauf von 2 Sek. [Quellwert] Feuerschaden erleidet. Bei einem kritischen Treffer erhöht sich dieser Schaden um 300%.", ["unresolvedValues"] = true }
entries[299377] = { ["name"] = "Tollkühne Kraft", ["text"] = "Azerit Essenz\nWenn eine Eurer Fähigkeiten nicht kritisch trifft, besteht eine hohe Chance, dass Ihr 'Tollkühne Kraft' erhaltet. Wenn 'Tollkühne Kraft' 20 Stapel erreicht, wird Euer kritischer Trefferwert 6 Sek. lang um 70% erhöht." }
entries[299378] = { ["name"] = "Die Ungezügelte Kraft", ["text"] = "Azerit Essenz\n40 Meter Reichweite\nSofort 45 sek. Abklingzeit\nEntfesselt die Kräfte in Eurem Herz von Azeroth und schießt Azeritsplitter auf Euer Ziel, das dadurch im Verlauf von 2 Sek. [Quellwert] Feuerschaden erleidet. Bei einem kritischen Treffer erhöht sich dieser Schaden um 300%.\n\nBei jedem kritischen Treffer durch 'Die Ungezügelte Kraft' wird das Ziel sofort von einem zusätzlichen Azeritsplitter getroffen (bis zu maximal 5 Splitter).", ["unresolvedValues"] = true }
entries[299379] = { ["name"] = "Okto-Griff", ["text"] = "30 Meter Reichweite\nSofort 10 sek. Abklingzeit\nHält das Ziel 3 Sek. lang an Ort und Stelle fest und verfüttert es dann an einen hungrigen Hai." }
